const API='/api';const S={token:localStorage.getItem('gx_token')||'',user:null,config:null,cat:'all',item:null,auth:'login',loyaltyPoints:0,pointsApplied:0};const $=id=>document.getElementById(id);const esc=s=>{const d=document.createElement('div');d.textContent=s??'';return d.innerHTML};
async function api(path,opt={}){const h={'Content-Type':'application/json',...(opt.headers||{})};if(S.token)h.Authorization='Bearer '+S.token;const r=await fetch(API+path,{...opt,headers:h});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'เกิดข้อผิดพลาด');return d}
function toast(x){const t=$('toast');t.textContent=x;t.classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>t.classList.remove('show'),2500)}
function setBtnLoading(el,loading,label){if(!el)return;if(loading){if(el.dataset.origHtml===undefined)el.dataset.origHtml=el.innerHTML;el.disabled=true;el.classList.add('loading');el.innerHTML='<span class="orbit-spinner" aria-hidden="true"></span><span>'+(label||'กำลังดำเนินการ')+'</span>'}else{el.disabled=false;el.classList.remove('loading');if(el.dataset.origHtml!==undefined){el.innerHTML=el.dataset.origHtml;delete el.dataset.origHtml}}}
function novaBurst(target){try{if(!target)return;const r=target.getBoundingClientRect();const b=document.createElement('div');b.className='nova-burst';b.style.left=(r.left+r.width/2)+'px';b.style.top=(r.top+r.height/2)+'px';document.body.appendChild(b);setTimeout(()=>b.remove(),900)}catch(e){}}
function handleDiscordRedirect(){const u=new URL(location.href);const token=u.searchParams.get('discordToken');const err=u.searchParams.get('discordError');if(token){S.token=token;localStorage.setItem('gx_token',token);toast('เข้าสู่ระบบด้วย Discord สำเร็จ')}if(err)toast(err);if(token||err){u.searchParams.delete('discordToken');u.searchParams.delete('discordError');history.replaceState({},'',u.pathname+u.search+u.hash)}}
async function init(){try{handleDiscordRedirect();handleResetTokenFromUrl();initNav();S.config=await api('/config');renderConfig();await session();renderAuth();await Promise.all([refreshStatus(),loadNews(),loadOrders(),loadLeaderboard(),loadLinked(),loadDiscordWidget(),loadLoyalty()]);setInterval(refreshStatus,60000)}catch(e){toast('ระบบเริ่มต้นไม่ได้: '+e.message)}}
async function loadLoyalty(){if(!S.user){S.loyaltyPoints=0;$('loyalty-points').textContent='เข้าสู่ระบบเพื่อดูแต้มสะสม';$('loyalty-history').innerHTML='';renderDashStats();return}try{const d=await api('/loyalty');S.loyaltyPoints=d.points;$('loyalty-points').textContent=d.points+' แต้ม';$('loyalty-history').innerHTML=d.history.length?d.history.map(h=>`<div class="order-row"><span>${esc(h.reason)}</span><span class="mono">${esc(h.createdAt)}</span><span class="${h.delta>0?'status':'status'}" style="color:${h.delta>0?'var(--signal)':'var(--danger)'}">${h.delta>0?'+':''}${h.delta}</span></div>`).join(''):'<div class="empty">ยังไม่มีประวัติแต้มสะสม</div>';renderDashStats()}catch{$('loyalty-points').textContent='โหลดแต้มไม่ได้'}}
function renderDashStats(){if(!$('dash-guest'))return;if(!S.user){$('dash-guest').style.display='block';$('dash-content').style.display='none';return}$('dash-guest').style.display='none';$('dash-content').style.display='block';$('dash-points').textContent=(S.loyaltyPoints||0)+' แต้ม';$('dash-order-count').textContent=(S.orders||[]).length;const totalSpent=(S.orders||[]).reduce((s,o)=>s+(Number(o.finalAmountThb)||0),0);$('dash-total-spent').textContent='฿'+totalSpent.toFixed(2);$('dash-member-since').textContent=S.user.createdAt?esc(String(S.user.createdAt).slice(0,10)):'—';$('dash-account-info').innerHTML=`<div class="order-row"><span>ชื่อผู้ใช้</span><span class="mono">${esc(S.user.username)}</span></div><div class="order-row"><span>อีเมล</span><span class="mono">${S.user.email?esc(S.user.email):'ยังไม่ได้ตั้งค่า'}</span></div><div class="order-row"><span>Discord</span><span class="mono">${S.user.discordUsername?esc(S.user.discordUsername):'ยังไม่เชื่อม'}</span></div>`;loadDashPlayerStats()}
async function loadDashPlayerStats(){if(!S.user)return;try{const d=await api('/players/'+encodeURIComponent(S.user.username));if(!d.player){$('dash-player-stats').innerHTML='<div class="empty">ยังไม่มีข้อมูลผู้เล่นในระบบสำหรับชื่อนี้</div>';$('dash-player-updated').textContent='';return}const p=d.player;$('dash-player-stats').innerHTML=`<div class="player-stats" style="margin-top:0"><div><small>LEVEL</small><b>${p.level??'—'}</b></div><div><small>PLAYTIME</small><b>${p.playtime??'—'}</b></div><div><small>BALANCE</small><b>${p.balance??'—'}</b></div></div>`;$('dash-player-updated').textContent=p.updatedAt?'อัปเดต '+esc(p.updatedAt):''}catch{$('dash-player-stats').innerHTML='<div class="empty">โหลดไม่ได้</div>'}}
async function changePassword(){const btn=$('pw-submit');const cur=$('pw-current').value,next=$('pw-new').value;if(next.length<8){$('pw-msg').textContent='รหัสผ่านใหม่ต้องมีอย่างน้อย 8 ตัวอักษร';return}setBtnLoading(btn,true,'กำลังบันทึก');try{await api('/account/password',{method:'POST',body:JSON.stringify({currentPassword:cur,newPassword:next})});$('pw-msg').textContent='เปลี่ยนรหัสผ่านสำเร็จ';$('pw-current').value='';$('pw-new').value='';novaBurst(btn);toast('เปลี่ยนรหัสผ่านสำเร็จ')}catch(e){$('pw-msg').textContent=e.message}finally{setBtnLoading(btn,false)}}
function goToDashboard(){closeOrder();closeAuth();location.hash='#account'}
function renderConfig(){const c=S.config;$('big-address').textContent=`${c.serverAddress}:${c.serverPort}`;$('s-port').textContent=c.serverPort;$('footer-address').textContent=`${c.serverAddress}:${c.serverPort}`;renderTabs();renderStore();$('events-grid').innerHTML=c.events.map(e=>`<article class="event card"><div class="event-date">${esc(e.date)}</div><h3>${esc(e.title)}</h3><p>${esc(e.desc)}</p></article>`).join('');$('staff-grid').innerHTML=c.staff.map(s=>`<article class="staff card"><div class="staff-avatar">${esc(s.emoji)}</div><b>${esc(s.name)}</b><span class="role">${esc(s.role)}</span></article>`).join('');$('rules-list').innerHTML=c.rules.map((r,i)=>`<article class="rule card"><span class="number">${String(i+1).padStart(2,'0')}</span><span>${r}</span></article>`).join('');$('faq-list').innerHTML=c.faq.map(f=>`<details><summary>${esc(f.q)}</summary><p>${esc(f.a)}</p></details>`).join('');if(c.discord?.loginEnabled){$('auth-discord-btn').style.display='flex';$('auth-discord-divider').style.display='flex'}}
async function loadDiscordWidget(){const box=$('discord-card');try{const d=await api('/discord/widget');if(!d.enabled){box.innerHTML=`<div class="discord-off">ยังไม่ได้เปิดใช้งาน Discord widget สำหรับเซิร์ฟเวอร์นี้${d.inviteUrl?` — <a href="${esc(d.inviteUrl)}" target="_blank" style="color:var(--cyan)">เข้าร่วม Discord ได้ที่นี่</a>`:''}</div>`;return}
box.innerHTML=`<div class="discord-info"><div class="discord-online"><i></i>${d.presenceCount} คนออนไลน์ใน ${esc(d.name||'Discord')}</div><div class="discord-avatars">${d.members.map(m=>m.avatarUrl?`<img src="${esc(m.avatarUrl)}" title="${esc(m.username)}" alt="">`:`<span class="fallback-avatar" title="${esc(m.username)}">${esc((m.username||'?')[0].toUpperCase())}</span>`).join('')}</div></div>${d.inviteUrl?`<a class="btn discord" href="${esc(d.inviteUrl)}" target="_blank">เข้าร่วม Discord</a>`:''}`}catch{box.innerHTML='<div class="discord-off">โหลดข้อมูล Discord ไม่ได้</div>'}}
async function refreshStatus(){try{const d=await api('/server/status');$('big-state').textContent=d.online?'ONLINE':'OFFLINE';$('big-state').style.color=d.online?'var(--cyan)':'var(--red)';$('s-players').textContent=d.online?`${d.players.online} / ${d.players.max}`:'—';$('s-version').textContent=d.version||'—';$('s-motd').textContent=d.motd||'—';$('server-chip').className='chip '+(d.online?'on':'off');$('server-chip').innerHTML=`<i></i><span>${d.online?'ONLINE':'OFFLINE'}</span>`}catch{$('big-state').textContent='UNAVAILABLE';$('big-state').style.color='var(--red)';$('server-chip').className='chip off';$('server-chip').innerHTML='<i></i><span>UNAVAILABLE</span>'}}
function copyAddress(){navigator.clipboard?.writeText(`${S.config.serverAddress}:${S.config.serverPort}`);toast('คัดลอก Server Address แล้ว')}
function toggleNav(){$('main-nav').classList.toggle('open');$('nav-toggle').classList.toggle('open')}
const PAGE_IDS=['home','news','store','players','events','team','discord','account','rules','faq','admin'];
function showPage(id){if(!PAGE_IDS.includes(id))id='home';PAGE_IDS.forEach(p=>{const el=$(p);if(el)el.classList.toggle('active',p===id)});
$('main-nav').querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+id));
$('main-nav').classList.remove('open');window.scrollTo(0,0)}
function initNav(){showPage((location.hash||'#home').slice(1));window.addEventListener('hashchange',()=>showPage(location.hash.slice(1)))}
async function loadNews(){try{const d=await api('/news');$('news-list').innerHTML=d.news.length?d.news.map(n=>`<article class="news-item card"><div class="news-date">${esc(n.date)}</div><div><b>${esc(n.title)}</b><span class="tag">${esc(n.tag)}</span><div class="news-body">${esc(n.body)}</div><div class="comments" id="comments-${n.id}"><div class="empty">กำลังโหลดคอมเมนต์…</div></div></div></article>`).join(''):'<div class="empty">ยังไม่มีประกาศ</div>';d.news.forEach(n=>loadComments(n.id))}catch{$('news-list').innerHTML='<div class="empty">โหลดข่าวสารไม่ได้</div>'}}
async function loadComments(newsId){try{const d=await api('/news/'+newsId+'/comments');const box=$('comments-'+newsId);if(!box)return;const list=d.comments.map(c=>`<div class="comment-row"><span><b>${esc(c.username)}</b><small>${esc(c.body)}</small></span>${(S.user&&S.user.id===c.userId)||(S.admin)?`<button class="btn ghost small" onclick="deleteComment(${c.id},${newsId})">ลบ</button>`:''}</div>`).join('')||'<div class="empty">ยังไม่มีความคิดเห็น เป็นคนแรกเลย!</div>';const form=S.user?`<div class="comment-form"><input id="comment-input-${newsId}" placeholder="แสดงความคิดเห็น…" onkeydown="if(event.key==='Enter')postComment(${newsId})"><button class="btn primary small" onclick="postComment(${newsId})">ส่ง</button></div>`:`<div class="empty">เข้าสู่ระบบเพื่อแสดงความคิดเห็น</div>`;box.innerHTML=list+form}catch{}}
async function postComment(newsId){const input=$('comment-input-'+newsId);const body=input.value.trim();if(!body)return;try{await api('/news/'+newsId+'/comments',{method:'POST',body:JSON.stringify({body})});input.value='';loadComments(newsId)}catch(e){toast(e.message)}}
async function deleteComment(id,newsId){if(!confirm('ลบความคิดเห็นนี้?'))return;try{if(S.admin)await api('/admin/comments/'+id,{method:'DELETE',headers:adminHeaders()});else await api('/comments/'+id,{method:'DELETE'});loadComments(newsId)}catch(e){toast(e.message)}}
function renderTabs(){const cats=S.config.shopCategories.filter(x=>x.id!=='gamble');$('store-tabs').innerHTML=cats.map(c=>`<button class="${S.cat===c.id?'active':''}" onclick="setCat('${esc(c.id)}')">${esc(c.name)}</button>`).join('')}
function setCat(c){S.cat=c;renderTabs();renderStore()}
function storeCard(i){const soldOut=i.stockRemaining!=null&&i.stockRemaining<=0;const stockBadge=i.stockRemaining!=null?`<span class="stock-badge ${soldOut?'out':''}">${soldOut?'สินค้าหมด':'เหลือ '+i.stockRemaining+' ชิ้น'}</span>`:'';return `<article class="store-item card"><div class="product-art">${i.image?`<img src="${esc(i.image)}" style="width:100%;height:100%;object-fit:cover" alt="">`:({cosmetic:'✦',gear:'⚔',rank:'♛',land:'⌂',collect:'◇'}[i.category]||'◈')}</div><b class="product-name">${esc(i.name)}</b>${stockBadge}<div class="product-desc">${esc(i.desc)}</div><div class="product-foot"><span class="price">${esc(i.price)}</span><button class="btn primary small" ${soldOut?'disabled':''} onclick="openOrder('${esc(i.id)}')">${soldOut?'หมด':'สั่งซื้อ'}</button></div></article>`}
function renderStore(){if(!S.config)return;const q=($('store-search').value||'').toLowerCase();const match=i=>i.category!=='gamble'&&(`${i.name} ${i.desc}`.toLowerCase().includes(q));
if(S.cat==='all'){const cats=S.config.shopCategories.filter(c=>c.id!=='all'&&c.id!=='gamble');const groups=cats.map(c=>({cat:c,items:S.config.shopItems.filter(i=>i.category===c.id&&match(i))})).filter(g=>g.items.length);$('store-grid').innerHTML=groups.length?groups.map(g=>`<div class="store-group"><div class="store-group-head"><h3>${esc(g.cat.name)}</h3><span>${g.items.length} รายการ</span></div><div class="store-grid-inner">${g.items.map(storeCard).join('')}</div></div>`).join(''):'<div class="empty">ไม่พบสินค้า</div>';return}
let items=S.config.shopItems.filter(i=>i.category===S.cat&&match(i));$('store-grid').innerHTML=items.length?`<div class="store-grid-inner">${items.map(storeCard).join('')}</div>`:'<div class="empty">ไม่พบสินค้า</div>'}
function openOrder(id){if(!S.user){openAuth('login');return}S.item=S.config.shopItems.find(x=>x.id===id);S.couponApplied=null;S.pointsApplied=0;$('order-title').textContent=S.item.name;$('order-qty').value=1;$('order-ign').value='';$('order-msg').textContent='';$('payment-box').innerHTML='';$('order-coupon').value='';$('coupon-msg').textContent='';$('coupon-box').style.display=S.item.cashPriceThb?'block':'none';$('order-points').value='';$('order-points').placeholder=`จำนวนแต้มที่จะใช้ (คุณมี ${S.loyaltyPoints} แต้ม)`;$('points-msg').textContent='';$('points-box').style.display=S.item.cashPriceThb&&S.loyaltyPoints>0?'block':'none';updateOrderPriceDisplay();$('order-form-view').style.display='block';$('order-success-view').style.display='none';$('order-modal').classList.add('show')}
function closeOrder(){$('order-modal').classList.remove('show')}
function getOrderQty(){return Math.max(1,Math.min(20,Math.floor(Number($('order-qty').value)||1)))}
function updateOrderPriceDisplay(){const qty=getOrderQty();$('order-price').textContent=S.item.price+(S.item.cashPriceThb?` · ฿${Number(S.item.cashPriceThb).toFixed(2)} / ชิ้น`:'');$('order-total').innerHTML=S.item.cashPriceThb?`<span>รวม ${qty} ชิ้น</span><span>฿${(S.item.cashPriceThb*qty).toFixed(2)}</span>`:''}
function changeOrderQty(delta){const el=$('order-qty');el.value=Math.max(1,Math.min(20,(Math.floor(Number(el.value)||1))+delta));onOrderQtyChange()}
function onOrderQtyChange(){const el=$('order-qty');el.value=Math.max(1,Math.min(20,Math.floor(Number(el.value)||1)));S.couponApplied=null;S.pointsApplied=0;$('coupon-msg').textContent='';$('points-msg').textContent='';updateOrderPriceDisplay()}
async function applyCoupon(){const code=$('order-coupon').value.trim();if(!code)return;const qty=getOrderQty();try{const d=await api('/coupons/check',{method:'POST',body:JSON.stringify({itemId:S.item.id,couponCode:code,quantity:qty})});S.couponApplied=code;$('coupon-msg').textContent=`ใช้โค้ดแล้ว: ลด ฿${d.discountThb.toFixed(2)}`;$('order-total').innerHTML=`<span>รวม ${qty} ชิ้น</span><span>฿${d.finalAmountThb.toFixed(2)}</span>`}catch(e){S.couponApplied=null;$('coupon-msg').textContent=e.message}}
async function applyPoints(){const pts=Math.floor(Number($('order-points').value)||0);if(!pts){$('points-msg').textContent='กรอกจำนวนแต้ม';return}const qty=getOrderQty();try{const d=await api('/loyalty/check',{method:'POST',body:JSON.stringify({itemId:S.item.id,points:pts,quantity:qty})});S.pointsApplied=pts;$('points-msg').textContent=`ใช้แต้มแล้ว: ลด ฿${d.discountThb.toFixed(2)}`;$('order-total').innerHTML=`<span>รวม ${qty} ชิ้น</span><span>฿${d.finalAmountThb.toFixed(2)}</span>`}catch(e){S.pointsApplied=0;$('points-msg').textContent=e.message}}
function showOrderSuccess(orderId,qty,amountThb){$('order-form-view').style.display='none';$('order-success-view').style.display='block';$('order-success-summary').innerHTML=`<div class="order-row"><span>สินค้า</span><span><b>${esc(S.item.name)}</b>${qty>1?' × '+qty:''}</span></div><div class="order-row"><span>เลขที่คำสั่งซื้อ</span><span class="mono">#${orderId}</span></div>${amountThb!=null?`<div class="order-row"><span>ยอดชำระ</span><span class="mono">฿${Number(amountThb).toFixed(2)}</span></div>`:''}<div class="order-row"><span>สถานะ</span><span class="status">${amountThb!=null?'ชำระเงินแล้ว':'รอดำเนินการ'}</span></div>`}
async function submitOrder(){const btn=$('order-submit');setBtnLoading(btn,true,'กำลังสั่งซื้อ');try{const qty=getOrderQty();const body={itemId:S.item.id,igName:$('order-ign').value.trim(),quantity:qty};if(S.couponApplied)body.couponCode=S.couponApplied;if(S.pointsApplied)body.redeemPoints=S.pointsApplied;const d=await api('/orders',{method:'POST',body:JSON.stringify(body)});novaBurst(btn);if(S.item.cashPriceThb){$('payment-box').innerHTML=`<div class=\"payment-card\"><b>ชำระเงินด้วย PromptPay</b><button class=\"btn primary full\" onclick=\"payPromptPay(${d.id},event)\">สร้าง QR สำหรับชำระเงิน</button><div id=\"payment-result\"></div></div>`;$('order-msg').textContent='สร้างคำสั่งซื้อ #'+d.id+' แล้ว กรุณาชำระเงินเพื่อดำเนินการต่อ'}else{showOrderSuccess(d.id,qty,null)}loadOrders();loadLoyalty()}catch(e){$('order-msg').textContent=e.message}finally{setBtnLoading(btn,false)}}
async function payPromptPay(id,ev){const btn=ev&&ev.target&&ev.target.closest?ev.target.closest('button'):null;setBtnLoading(btn,true,'กำลังตรวจสอบการชำระเงิน');try{const d=await api('/orders/'+id+'/pay/promptpay',{method:'POST'});if(d.paid){novaBurst(btn||$('payment-box'));showOrderSuccess(id,getOrderQty(),d.amountThb);loadOrders();loadLoyalty();return}const qr=d.qrUrl?`<img src=\"${esc(d.qrUrl)}\" alt=\"PromptPay QR\" style=\"width:220px;max-width:100%;border-radius:14px;margin-top:10px\">`:'<div class=\"empty\">ผู้ให้บริการยังไม่ส่ง QR URL กลับมา</div>';$('payment-result').innerHTML=`<div class=\"msg\">ยอด ฿${Number(d.amountThb).toFixed(2)} · สถานะ ${esc(d.status||'pending')}</div>${qr}<div class=\"empty\">หลังชำระแล้วให้รอระบบ Webhook อัปเดตสถานะ</div>`}catch(e){$('payment-result').innerHTML='<div class=\"msg\">'+esc(e.message)+'</div>'}finally{setBtnLoading(btn,false)}}
async function loadOrders(){if(!S.user){$('orders-list').innerHTML='<div class="empty">เข้าสู่ระบบเพื่อดูคำสั่งซื้อ</div>';S.orders=[];renderDashStats();return}try{const d=await api('/orders');S.orders=d.orders;$('orders-list').innerHTML=d.orders.length?d.orders.map(o=>`<div class="order-row"><span><b>${esc(o.itemName)}</b>${o.quantity>1?' × '+o.quantity:''}<br><span style="color:var(--muted)">${esc(o.igName)}${o.finalAmountThb!=null?' · ฿'+Number(o.finalAmountThb).toFixed(2):''}</span></span><span class="mono">${esc(o.createdAt)}</span><span class="status">${esc(o.status)}</span>${o.paymentStatus==='paid'?`<button class="btn ghost small" onclick="viewReceipt(${o.id})">ใบเสร็จ</button>`:''}</div>`).join(''):'<div class="empty">ยังไม่มีคำสั่งซื้อ</div>';renderDashStats()}catch{$('orders-list').innerHTML='<div class="empty">โหลดไม่ได้</div>'}}
async function viewReceipt(id){try{const d=await api('/orders/'+id+'/receipt');const r=d.receipt;$('receipt-body').innerHTML=`<div><span>เลขที่คำสั่งซื้อ</span><span>#${r.orderId}</span></div><div><span>สินค้า</span><span>${esc(r.item)}</span></div><div><span>ผู้เล่น IGN</span><span>${esc(r.igName)}</span></div><div><span>ราคา</span><span>฿${Number(r.priceThb).toFixed(2)}</span></div>${r.couponCode?`<div><span>โค้ดส่วนลด (${esc(r.couponCode)})</span><span>-฿${Number(r.discountThb).toFixed(2)}</span></div>`:''}<div><span>ชำระผ่าน</span><span>${esc(r.paymentProvider||'-')}</span></div><div><span>วันที่ชำระ</span><span>${esc(r.paidAt||'-')}</span></div><div><span>ยอดชำระสุทธิ</span><span>฿${Number(r.totalThb).toFixed(2)}</span></div>`;$('receipt-modal').classList.add('show')}catch(e){toast(e.message)}}
async function lookupPlayer(){const n=$('player-input').value.trim();if(!n)return;try{const d=await api('/players/'+encodeURIComponent(n));if(!d.player){$('player-result').innerHTML='<div class="empty">ไม่พบผู้เล่นในฐานข้อมูล</div>';$('player-result').classList.add('show');return}const p=d.player;$('player-result').innerHTML=`<div class="player-head"><div class="avatar">${esc(p.name[0])}</div><div><b>${esc(p.name)}</b><div style="color:var(--muted);font-size:.72rem">${esc(p.gamertag||'ยังไม่เชื่อม Xbox')}</div></div></div><div class="player-stats"><div><small>LEVEL</small><b>${p.level??'—'}</b></div><div><small>PLAYTIME</small><b>${p.playtime??'—'}</b></div><div><small>BALANCE</small><b>${p.balance??'—'}</b></div></div><div class="empty">อัปเดตล่าสุด: ${esc(p.updatedAt||'—')}</div>`;$('player-result').classList.add('show')}catch(e){toast(e.message)}}
async function loadLeaderboard(){try{const d=await api('/leaderboard');$('lb-source').textContent=d.source==='server'?'SERVER DATA':'ยังไม่มีข้อมูล';$('leaderboard').innerHTML=d.players.length?d.players.map((p,i)=>`<div class="lb-row"><span class="rank">${String(i+1).padStart(2,'0')}</span><b>${esc(p.name)}</b><span class="score">${esc(String(p.hours))} h</span></div>`).join(''):'<div class="empty">ยังไม่มีข้อมูลผู้เล่น</div>'}catch{}}
async function session(){if(!S.token)return;try{S.user=(await api('/me')).user}catch{S.token='';localStorage.removeItem('gx_token')}}
function renderAuth(){$('auth-area').innerHTML=S.user?`<button class="btn ghost small" onclick="logout()">${esc(S.user.username)} · ออก</button>`:'<button class="btn primary small" onclick="openAuth(\'login\')">เข้าสู่ระบบ</button>'}
function openAuth(m){S.auth=m;$('auth-title').textContent=m==='login'?'เข้าสู่ระบบ':'สมัครสมาชิก';$('auth-submit').textContent=m==='login'?'เข้าสู่ระบบ':'สร้างบัญชี';$('auth-msg').textContent='';$('auth-email').style.display=m==='register'?'block':'none';$('forgot-pass-link').style.display=m==='login'?'block':'none';$('auth-modal').classList.add('show')}
function closeAuth(){$('auth-modal').classList.remove('show')}
function toggleAuth(){openAuth(S.auth==='login'?'register':'login')}
async function submitAuth(){const btn=$('auth-submit');setBtnLoading(btn,true,S.auth==='login'?'กำลังเข้าสู่ระบบ':'กำลังสมัครสมาชิก');try{const body={username:$('auth-user').value.trim(),password:$('auth-pass').value};if(S.auth==='register')body.email=$('auth-email').value.trim();const d=await api(S.auth==='login'?'/auth/login':'/auth/register',{method:'POST',body:JSON.stringify(body)});S.token=d.token;S.user=d.user;localStorage.setItem('gx_token',S.token);novaBurst(btn);closeAuth();renderAuth();await Promise.all([loadOrders(),loadLinked(),loadLoyalty()]);toast(S.auth==='login'?'เข้าสู่ระบบสำเร็จ':'สมัครสมาชิกสำเร็จ')}catch(e){$('auth-msg').textContent=e.message}finally{setBtnLoading(btn,false)}}
function openForgotPassword(){closeAuth();$('forgot-email').value='';$('forgot-msg').textContent='';$('forgot-modal').classList.add('show')}
async function submitForgotPassword(){try{const d=await api('/auth/forgot-password',{method:'POST',body:JSON.stringify({email:$('forgot-email').value.trim()})});$('forgot-msg').textContent=d.message||'ส่งลิงก์แล้ว ถ้ามีอีเมลนี้ในระบบ'}catch(e){$('forgot-msg').textContent=e.message}}
function handleResetTokenFromUrl(){const u=new URL(location.href);const token=u.searchParams.get('resetToken');if(!token)return;S.resetToken=token;$('reset-pass').value='';$('reset-msg').textContent='';$('reset-modal').classList.add('show');u.searchParams.delete('resetToken');history.replaceState({},'',u.pathname+u.search+u.hash)}
async function submitResetPassword(){try{await api('/auth/reset-password',{method:'POST',body:JSON.stringify({token:S.resetToken,password:$('reset-pass').value})});$('reset-modal').classList.remove('show');toast('ตั้งรหัสผ่านใหม่สำเร็จ กรุณาเข้าสู่ระบบ');openAuth('login')}catch(e){$('reset-msg').textContent=e.message}}
function logout(){S.token='';S.user=null;localStorage.removeItem('gx_token');renderAuth();loadOrders();loadLinked();loadLoyalty();toast('ออกจากระบบแล้ว')}
async function linkXbox(){if(!S.user){openAuth('login');return}try{await api('/account/xbox',{method:'POST',body:JSON.stringify({gamertag:$('xbox-tag').value.trim(),igName:$('xbox-ign').value.trim()})});$('xbox-msg').textContent='บันทึกแล้ว';loadLinked()}catch(e){$('xbox-msg').textContent=e.message}}
async function loadLinked(){if(!S.user){$('linked-list').innerHTML='<div class="empty">เข้าสู่ระบบเพื่อดูบัญชีที่เชื่อม</div>';return}try{const d=await api('/account/xbox');$('linked-list').innerHTML=d.links.length?d.links.map(x=>`<div class="order-row"><span>${esc(x.igName)}</span><span class="mono">${esc(x.gamertag)}</span></div>`).join(''):'<div class="empty">ยังไม่มีบัญชีที่เชื่อม</div>'}catch{} }
S.adminToken=localStorage.getItem('gx_admin_token')||'';S.admin=null;
function adminHeaders(){return {Authorization:'Bearer '+S.adminToken}}
const ROLE_LABEL={owner:'OWNER',admin:'ADMIN',moderator:'MODERATOR'};
async function initAdminSection(){
  if(S.adminToken){try{S.admin=(await api('/admin/me',{headers:adminHeaders()})).admin;showAdminSession();await loadAdmin();return}catch{S.adminToken='';localStorage.removeItem('gx_admin_token')}}
  try{const st=await api('/admin/auth/status');if(!st.hasAdmins){$('admin-setup').style.display='block';$('admin-login').style.display='none'}else{$('admin-setup').style.display='none';$('admin-login').style.display='block'}}catch{}
}
function showAdminSession(){$('admin-setup').style.display='none';$('admin-login').style.display='none';$('admin-session').style.display='block';$('admin-tabs').style.display='flex';$('admin-whoami').textContent=`${S.admin.username} · ${ROLE_LABEL[S.admin.role]}`;$('tab-btn-accounts').style.display=S.admin.role==='owner'?'flex':'none';$('tab-btn-audit').style.display=S.admin.role==='owner'?'flex':'none'}
function setAdminTab(tab){S.adminTab=tab;['overview','content','players','users','xbox','coupons','sales','accounts','audit'].forEach(t=>{$('admin-pane-'+t).style.display=t===tab?'block':'none';const b=$('tab-btn-'+t);if(b)b.classList.toggle('active',t===tab)});if(tab==='players')loadAdminPlayers();if(tab==='users')loadAdminUsers();if(tab==='xbox')loadAdminXbox();if(tab==='coupons')loadAdminCoupons();if(tab==='sales')loadAdminSales();if(tab==='accounts')loadAdminAccounts();if(tab==='audit')loadAdminAuditLog()}
async function loadAdminAuditLog(){try{const d=await api('/admin/audit-log',{headers:adminHeaders()});$('admin-audit').innerHTML=`<div class="card form-card"><div class="card-title"><b>Audit log</b><span>ประวัติการทำรายการของแอดมินทุกคน (200 รายการล่าสุด)</span></div><div class="admin-list">${d.log.map(l=>`<div class="admin-line"><span><b>${esc(l.action)}</b><small>${esc(l.adminUsername)}${l.target?' · เป้าหมาย '+esc(l.target):''}${l.details?' · '+esc(JSON.stringify(l.details)):''} · ${esc(l.ip||'-')}</small></span><span class="mono" style="white-space:nowrap">${esc(l.createdAt)}</span></div>`).join('')||'<div class="empty">ยังไม่มีประวัติ</div>'}</div></div>`}catch(e){toast(e.message)}}
async function adminSetup(){try{const d=await api('/admin/auth/setup',{method:'POST',body:JSON.stringify({bootstrapKey:$('setup-bootstrap').value.trim(),username:$('setup-user').value.trim(),password:$('setup-pass').value})});S.adminToken=d.token;S.admin=d.admin;localStorage.setItem('gx_admin_token',S.adminToken);showAdminSession();await loadAdmin();toast('สร้างบัญชี Owner สำเร็จ')}catch(e){$('setup-msg').textContent=e.message}}
async function adminLogin(){try{const d=await api('/admin/auth/login',{method:'POST',body:JSON.stringify({username:$('admin-user').value.trim(),password:$('admin-pass').value})});if(d.requires2fa){promptAdmin2faLogin(d.pendingToken);return}S.adminToken=d.token;S.admin=d.admin;localStorage.setItem('gx_admin_token',S.adminToken);showAdminSession();await loadAdmin();toast('เข้าสู่ระบบแอดมินสำเร็จ')}catch(e){$('admin-msg').textContent=e.message}}
function promptAdmin2faLogin(pendingToken){$('admin-2fa-body').innerHTML=`<p style="color:var(--muted);font-size:.82rem">บัญชีนี้เปิด 2FA ไว้ กรอกรหัส 6 หลักจากแอป Authenticator</p><input id="admin-2fa-login-code" placeholder="123456" maxlength="6"><button class="btn primary full" onclick="confirmAdmin2faLogin('${pendingToken}')" style="margin-top:8px">ยืนยัน</button><div id="admin-2fa-login-msg" class="msg"></div>`;$('admin-2fa-modal').classList.add('show')}
async function confirmAdmin2faLogin(pendingToken){try{const d=await api('/admin/auth/login/2fa',{method:'POST',body:JSON.stringify({pendingToken,code:$('admin-2fa-login-code').value.trim()})});S.adminToken=d.token;S.admin=d.admin;localStorage.setItem('gx_admin_token',S.adminToken);$('admin-2fa-modal').classList.remove('show');showAdminSession();await loadAdmin();toast('เข้าสู่ระบบแอดมินสำเร็จ')}catch(e){$('admin-2fa-login-msg').textContent=e.message}}
function adminLogout(){S.adminToken='';S.admin=null;localStorage.removeItem('gx_admin_token');$('admin-session').style.display='none';$('admin-panel').innerHTML='';$('admin-content').innerHTML='';$('admin-accounts').innerHTML='';initAdminSection();toast('ออกจากระบบแอดมินแล้ว')}
const ORDER_STATUSES=['รอดำเนินการ','รอชำระเงิน','ชำระเงินแล้ว','กำลังดำเนินการ','ส่งแล้ว','ยกเลิก','การชำระเงินไม่สำเร็จ','คืนเงินแล้ว'];
S.orderFilter={status:'',q:'',page:1};
const ADM_QUICKLINKS=[{tab:'content',label:'Content',desc:'ข่าว สินค้า กิจกรรม'},{tab:'players',label:'Players',desc:'ข้อมูลผู้เล่น'},{tab:'users',label:'Users',desc:'บัญชีผู้เล่น'},{tab:'xbox',label:'Xbox links',desc:'บัญชีที่เชื่อม Xbox'},{tab:'coupons',label:'Coupons',desc:'โค้ดส่วนลด'},{tab:'sales',label:'Sales',desc:'สถิติยอดขาย'}];
async function loadAdmin(){try{const h=adminHeaders();const d=await api('/admin/overview',{headers:h});const c=await api('/admin/content',{headers:h});$('admin-panel').innerHTML=`<div class="admin-stats"><div class="admin-stat card"><small>USERS</small><b>${d.stats.users}</b></div><div class="admin-stat card"><small>ORDERS</small><b>${d.stats.orders}</b></div><div class="admin-stat card"><small>PLAYERS</small><b>${d.stats.players}</b></div><div class="admin-stat card"><small>NEWS</small><b>${d.stats.news}</b></div></div><div class="admin-quicklinks">${ADM_QUICKLINKS.map(q=>`<button class="adm-quick card" onclick="setAdminTab('${q.tab}')"><b>${esc(q.label)}</b><span>${esc(q.desc)}</span></button>`).join('')}</div><div class="admin-table card"><div class="card-title"><b>Orders</b><span id="orders-count"></span></div><div class="admin-filters"><input id="ord-q" placeholder="ค้นหา user / IGN / สินค้า" oninput="ordFilterDebounced()"><select id="ord-status" onchange="ordSetStatusFilter()"><option value="">ทุกสถานะ</option>${ORDER_STATUSES.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select></div><div id="orders-table-wrap"></div></div>`;renderAdminContent(c);loadOrdersTab();if(S.admin.role==='owner')loadAdminAccounts();else $('admin-accounts').innerHTML=''}catch(e){toast(e.message)}}
let ordDebounceT;function ordFilterDebounced(){clearTimeout(ordDebounceT);ordDebounceT=setTimeout(()=>{S.orderFilter.q=$('ord-q').value.trim();S.orderFilter.page=1;loadOrdersTab()},350)}
function ordSetStatusFilter(){S.orderFilter.status=$('ord-status').value;S.orderFilter.page=1;loadOrdersTab()}
function ordGoPage(p){S.orderFilter.page=p;loadOrdersTab()}
async function loadOrdersTab(){try{const f=S.orderFilter;const qs=new URLSearchParams({page:f.page,...(f.status?{status:f.status}:{}),...(f.q?{q:f.q}:{})});const d=await api('/admin/orders?'+qs.toString(),{headers:adminHeaders()});$('orders-count').textContent=`${d.total} รายการ · หน้า ${d.page}/${d.pages}`;$('orders-table-wrap').innerHTML=`<table><thead><tr><th>ID</th><th>User</th><th>Item</th><th>IGN</th><th>Status</th><th>Payment</th><th>Delivery command</th><th></th></tr></thead><tbody>${d.orders.map(o=>`<tr><td>#${o.id}</td><td>${esc(o.username)}</td><td>${esc(o.itemName)}</td><td>${esc(o.igName)}</td><td><select id="ord-st-${o.id}">${ORDER_STATUSES.map(s=>`<option ${o.status===s?'selected':''}>${esc(s)}</option>`).join('')}</select></td><td><span class="status">${esc(o.paymentStatus)}</span></td><td><input id="ord-cmd-${o.id}" value="${esc(o.deliveryCommand||'')}" placeholder="/give ${esc(o.igName)} ..." style="width:100%"></td><td style="white-space:nowrap"><button class="btn primary small" onclick="adminOrderSave(${o.id})">บันทึก</button> <button class="btn danger small" onclick="adminOrderRefund(${o.id})">ยกเลิก/คืนเงิน</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">ไม่พบคำสั่งซื้อ</td></tr>'}</tbody></table><div class="pager">${Array.from({length:d.pages},(_,i)=>i+1).map(p=>`<button class="${p===d.page?'active':''}" onclick="ordGoPage(${p})">${p}</button>`).join('')}</div>`}catch(e){toast(e.message)}}
async function adminOrderSave(id){try{await api('/admin/orders/'+id,{method:'PATCH',headers:adminHeaders(),body:JSON.stringify({status:$('ord-st-'+id).value,deliveryCommand:$('ord-cmd-'+id).value.trim()})});toast('บันทึกคำสั่งซื้อ #'+id+' แล้ว');loadOrdersTab()}catch(e){toast(e.message)}}
async function adminOrderRefund(id){if(!confirm('ยกเลิกคำสั่งซื้อนี้? ถ้าชำระผ่าน PromptPay แล้วระบบจะพยายามคืนเงินอัตโนมัติ'))return;try{const d=await api('/admin/orders/'+id+'/refund',{method:'POST',headers:adminHeaders()});toast(d.refunded?'คืนเงินสำเร็จ':(d.note||'ยกเลิกคำสั่งซื้อแล้ว'));loadOrdersTab()}catch(e){toast(e.message)}}
function renderAdminContent(c){const locked=S.admin.role==='moderator';$('admin-content').innerHTML=locked?'<div class="empty">บัญชีระดับ Moderator ดูแลได้เฉพาะคำสั่งซื้อด้านบน การแก้ไขข่าว/สินค้า/กิจกรรมต้องใช้สิทธิ์ Admin ขึ้นไป</div>':`<div class="admin-editor-grid"><div class="card form-card"><div class="card-title"><b>Publish news</b><span>ประกาศใหม่</span></div><input id="adm-news-title" placeholder="หัวข้อประกาศ"><textarea id="adm-news-body" placeholder="รายละเอียด"></textarea><select id="adm-news-tag"><option value="update">UPDATE</option><option value="event">EVENT</option><option value="maint">MAINT</option></select><button class="btn primary" onclick="adminNews()">เผยแพร่ประกาศ</button><div id="adm-news-msg" class="msg"></div><div class="admin-list">${c.news.map(n=>`<div class="admin-line"><span><b>${esc(n.title)}</b><small>${esc(n.date)} · ${esc(n.tag)}</small></span><button class="btn danger small" onclick="deleteNews(${n.id})">ลบ</button></div>`).join('')||'<div class="empty">ยังไม่มีประกาศ</div>'}</div></div><div class="card form-card"><div class="card-title"><b>Add product</b><span>สินค้าในฐานข้อมูล</span></div><input id="adm-p-id" placeholder="ID เช่น vip30"><input id="adm-p-name" placeholder="ชื่อสินค้า"><input id="adm-p-category" placeholder="หมวด เช่น rank"><input id="adm-p-price" placeholder="ราคาในเกม เช่น 150 เหรียญ"><input id="adm-p-cash" type="number" min="0" step="0.01" placeholder="ราคาจริง THB เช่น 49"><input id="adm-p-stock" type="number" min="0" placeholder="จำกัดสต็อก (เว้นว่าง=ไม่จำกัด)"><input id="adm-p-image" placeholder="Image URL (ถ้ามี)"><textarea id="adm-p-desc" placeholder="รายละเอียดสินค้า"></textarea><button class="btn primary" onclick="adminProduct()">เพิ่มสินค้า</button><div id="adm-p-msg" class="msg"></div><div class="admin-list">${c.products.map(x=>`<div class="admin-line"><span><b>${esc(x.name)}</b><small>${esc(x.id)} · ${esc(x.price)} · ${x.stockLimit!=null?'สต็อก '+x.stockRemaining+'/'+x.stockLimit+' · ':''}${x.active?'เปิด':'ปิด'}</small></span><span style="display:flex;gap:6px">${x.stockLimit!=null?`<button class="btn ghost small" onclick="adminRestock('${esc(x.id)}')">เติมสต็อก</button>`:''}<button class="btn danger small" onclick="deleteProduct('${esc(x.id)}')">ลบ</button></span></div>`).join('')}</div></div><div class="card form-card"><div class="card-title"><b>Add event</b><span>กิจกรรม</span></div><input id="adm-e-date" placeholder="เช่น 30 ก.ย. 2569 · 20:00"><input id="adm-e-title" placeholder="ชื่อกิจกรรม"><textarea id="adm-e-desc" placeholder="รายละเอียดกิจกรรม"></textarea><button class="btn primary" onclick="adminEvent()">เพิ่มกิจกรรม</button><div id="adm-e-msg" class="msg"></div><div class="admin-list">${c.events.map(x=>`<div class="admin-line"><span><b>${esc(x.title)}</b><small>${esc(x.date)}</small></span><button class="btn danger small" onclick="deleteEvent(${x.id})">ลบ</button></div>`).join('')||'<div class="empty">ยังไม่มีกิจกรรม</div>'}</div></div></div>`}
async function adminNews(){try{await api('/admin/news',{method:'POST',headers:adminHeaders(),body:JSON.stringify({title:$('adm-news-title').value.trim(),body:$('adm-news-body').value.trim(),tag:$('adm-news-tag').value})});$('adm-news-msg').textContent='เผยแพร่แล้ว';$('adm-news-title').value='';$('adm-news-body').value='';await loadNews();await loadAdmin();toast('เพิ่มประกาศแล้ว')}catch(e){$('adm-news-msg').textContent=e.message}}
async function deleteNews(id){if(!confirm('ลบประกาศนี้?'))return;try{await api('/admin/news/'+id,{method:'DELETE',headers:adminHeaders()});await loadNews();await loadAdmin();toast('ลบประกาศแล้ว')}catch(e){toast(e.message)}}
async function adminProduct(){try{await api('/admin/products',{method:'POST',headers:adminHeaders(),body:JSON.stringify({id:$('adm-p-id').value.trim(),name:$('adm-p-name').value.trim(),category:$('adm-p-category').value.trim(),price:$('adm-p-price').value.trim(),image:$('adm-p-image').value.trim(),description:$('adm-p-desc').value.trim(),cashPriceThb:$('adm-p-cash').value.trim(),stockLimit:$('adm-p-stock').value.trim()})});await refreshConfig();await loadAdmin();toast('เพิ่มสินค้าแล้ว')}catch(e){$('adm-p-msg').textContent=e.message}}
async function adminRestock(id){const n=prompt('เติมสต็อกเหลือเท่าไหร่ (ชิ้น)?');if(n==null)return;try{await api('/admin/products/'+encodeURIComponent(id),{method:'PATCH',headers:adminHeaders(),body:JSON.stringify({stockRemaining:Number(n)})});await refreshConfig();await loadAdmin();toast('เติมสต็อกแล้ว')}catch(e){toast(e.message)}}
async function deleteProduct(id){if(!confirm('ลบสินค้านี้?'))return;try{await api('/admin/products/'+encodeURIComponent(id),{method:'DELETE',headers:adminHeaders()});await refreshConfig();await loadAdmin();toast('ลบสินค้าแล้ว')}catch(e){toast(e.message)}}
async function adminEvent(){try{await api('/admin/events',{method:'POST',headers:adminHeaders(),body:JSON.stringify({date:$('adm-e-date').value.trim(),title:$('adm-e-title').value.trim(),description:$('adm-e-desc').value.trim()})});await refreshConfig();await loadAdmin();toast('เพิ่มกิจกรรมแล้ว')}catch(e){$('adm-e-msg').textContent=e.message}}
async function deleteEvent(id){if(!confirm('ลบกิจกรรมนี้?'))return;try{await api('/admin/events/'+id,{method:'DELETE',headers:adminHeaders()});await refreshConfig();await loadAdmin();toast('ลบกิจกรรมแล้ว')}catch(e){toast(e.message)}}
async function refreshConfig(){S.config=await api('/config');renderConfig()}
async function loadAdminAccounts(){try{const d=await api('/admin/accounts',{headers:adminHeaders()});$('admin-accounts').innerHTML=`<div class="card form-card"><div class="card-title"><b>Admin accounts</b><span>เฉพาะ Owner</span></div><input id="adm-a-user" placeholder="Username"><input id="adm-a-pass" type="password" placeholder="Password (อย่างน้อย 10 ตัว)"><select id="adm-a-role"><option value="moderator">MODERATOR</option><option value="admin">ADMIN</option><option value="owner">OWNER</option></select><button class="btn primary" onclick="adminCreateAccount()">เพิ่มบัญชีแอดมิน</button><div id="adm-a-msg" class="msg"></div><div class="admin-list">${d.accounts.map(a=>`<div class="admin-line"><span><b>${esc(a.username)}</b><small>${ROLE_LABEL[a.role]}${a.lastLoginAt?' · ล็อกอินล่าสุด '+esc(a.lastLoginAt):''}</small></span>${a.id===S.admin.id?'<span class="status">คุณ</span>':`<button class="btn danger small" onclick="adminDeleteAccount(${a.id})">ลบ</button>`}</div>`).join('')}</div></div>`}catch(e){toast(e.message)}}
async function adminCreateAccount(){try{await api('/admin/accounts',{method:'POST',headers:adminHeaders(),body:JSON.stringify({username:$('adm-a-user').value.trim(),password:$('adm-a-pass').value,role:$('adm-a-role').value})});$('adm-a-user').value='';$('adm-a-pass').value='';toast('เพิ่มบัญชีแอดมินแล้ว');loadAdminAccounts()}catch(e){$('adm-a-msg').textContent=e.message}}
async function adminDeleteAccount(id){if(!confirm('ลบบัญชีแอดมินนี้?'))return;try{await api('/admin/accounts/'+id,{method:'DELETE',headers:adminHeaders()});toast('ลบบัญชีแล้ว');loadAdminAccounts()}catch(e){toast(e.message)}}
// --- Players admin panel ---
S.playerPage=1;
async function loadAdminPlayers(q){try{const qs=new URLSearchParams({page:S.playerPage,...(q?{q}:{})});const d=await api('/admin/players?'+qs.toString(),{headers:adminHeaders()});renderAdminPlayers(d)}catch(e){toast(e.message)}}
function renderAdminPlayers(d){const locked=S.admin.role==='moderator';$('admin-players').innerHTML=`<div class="card form-card"><div class="card-title"><b>Players</b><span>${d.total} คน · ข้อมูลนี้ใช้แสดงผลใน Player lookup / Leaderboard</span></div><input id="plr-q" placeholder="ค้นหาชื่อผู้เล่น / gamertag" oninput="plrSearchDebounced()">${locked?'':`<div class="admin-editor-grid" style="grid-template-columns:repeat(2,1fr)"><input id="plr-name" placeholder="ชื่อผู้เล่น (IGN)"><input id="plr-gt" placeholder="Xbox gamertag"><input id="plr-level" type="number" placeholder="Level"><input id="plr-playtime" type="number" step="0.1" placeholder="Playtime (ชั่วโมง)"><input id="plr-balance" type="number" step="0.01" placeholder="Balance (เหรียญในเกม)"></div><button class="btn primary" onclick="adminSavePlayer()">บันทึก / เพิ่มผู้เล่น</button><div id="plr-msg" class="msg"></div>`}<div class="admin-list">${d.players.map(p=>`<div class="admin-line"><span><b>${esc(p.name)}</b><small>${esc(p.gamertag||'ไม่มี gamertag')} · Lv.${p.level??'—'} · ${p.playtime??'—'} ชม. · ${p.balance??'—'} เหรียญ</small></span>${locked?'':`<button class="btn danger small" onclick="adminDeletePlayer('${esc(p.name)}')">ลบ</button>`}</div>`).join('')||'<div class="empty">ยังไม่มีข้อมูลผู้เล่น</div>'}</div><div class="pager">${Array.from({length:d.pages},(_,i)=>i+1).map(p=>`<button class="${p===d.page?'active':''}" onclick="plrGoPage(${p})">${p}</button>`).join('')}</div></div>`}
let plrDebounceT;function plrSearchDebounced(){clearTimeout(plrDebounceT);plrDebounceT=setTimeout(()=>{S.playerPage=1;loadAdminPlayers($('plr-q').value.trim())},350)}
function plrGoPage(p){S.playerPage=p;loadAdminPlayers($('plr-q')?.value.trim())}
async function adminSavePlayer(){try{await api('/admin/players',{method:'POST',headers:adminHeaders(),body:JSON.stringify({name:$('plr-name').value.trim(),gamertag:$('plr-gt').value.trim(),level:$('plr-level').value,playtime:$('plr-playtime').value,balance:$('plr-balance').value})});$('plr-name').value='';$('plr-gt').value='';$('plr-level').value='';$('plr-playtime').value='';$('plr-balance').value='';toast('บันทึกผู้เล่นแล้ว');loadAdminPlayers()}catch(e){$('plr-msg').textContent=e.message}}
async function adminDeletePlayer(name){if(!confirm('ลบข้อมูลผู้เล่น '+name+'?'))return;try{await api('/admin/players/'+encodeURIComponent(name),{method:'DELETE',headers:adminHeaders()});toast('ลบผู้เล่นแล้ว');loadAdminPlayers()}catch(e){toast(e.message)}}

// --- Users admin panel ---
S.userPage=1;
async function loadAdminUsers(q){try{const qs=new URLSearchParams({page:S.userPage,...(q?{q}:{})});const d=await api('/admin/users?'+qs.toString(),{headers:adminHeaders()});renderAdminUsers(d)}catch(e){toast(e.message)}}
function renderAdminUsers(d){const locked=S.admin.role==='moderator';$('admin-users').innerHTML=`<div class="card form-card"><div class="card-title"><b>Users</b><span>${d.total} บัญชี</span></div><input id="usr-q" placeholder="ค้นหา username" oninput="usrSearchDebounced()"><div class="admin-list">${d.users.map(u=>`<div class="admin-line"><span><b>${esc(u.username)}</b><small>${u.orderCount} คำสั่งซื้อ · ${u.loyaltyPoints??0} แต้มสะสม · สมัคร ${esc(u.createdAt)} ${u.suspended?'· <span style=\"color:var(--red)\">ถูกระงับ</span>':''}</small></span>${locked?'':`<span style="display:flex;gap:6px"><button class="btn ghost small" onclick="adminAdjustPoints(${u.id},'${esc(u.username)}')">ปรับแต้ม</button><button class="btn ghost small" onclick="adminToggleSuspend(${u.id},${u.suspended?0:1})">${u.suspended?'ปลดระงับ':'ระงับ'}</button><button class="btn ghost small" onclick="adminResetUserPassword(${u.id})">รีเซ็ตรหัสผ่าน</button>${S.admin.role==='owner'?`<button class="btn danger small" onclick="adminDeleteUser(${u.id},'${esc(u.username)}')">ลบ</button>`:''}</span>`}</div>`).join('')||'<div class="empty">ยังไม่มีผู้ใช้</div>'}</div><div class="pager">${Array.from({length:d.pages},(_,i)=>i+1).map(p=>`<button class="${p===d.page?'active':''}" onclick="usrGoPage(${p})">${p}</button>`).join('')}</div></div>`}
async function adminAdjustPoints(id,username){const delta=prompt(`ปรับแต้มสะสมของ ${username} (ใส่ตัวเลข เช่น 50 หรือ -20):`);if(delta==null||!delta.trim())return;const n=Math.trunc(Number(delta));if(!Number.isFinite(n)||n===0){toast('กรุณากรอกตัวเลขที่ไม่เป็นศูนย์');return}const reason=prompt('เหตุผล (ไม่บังคับ):','')||'';try{await api('/admin/users/'+id+'/loyalty',{method:'POST',headers:adminHeaders(),body:JSON.stringify({delta:n,reason})});toast('ปรับแต้มแล้ว');loadAdminUsers($('usr-q')?.value.trim())}catch(e){toast(e.message)}}
let usrDebounceT;function usrSearchDebounced(){clearTimeout(usrDebounceT);usrDebounceT=setTimeout(()=>{S.userPage=1;loadAdminUsers($('usr-q').value.trim())},350)}
function usrGoPage(p){S.userPage=p;loadAdminUsers($('usr-q')?.value.trim())}
async function adminToggleSuspend(id,suspended){try{await api('/admin/users/'+id,{method:'PATCH',headers:adminHeaders(),body:JSON.stringify({suspended:!!suspended})});toast(suspended?'ระงับบัญชีแล้ว':'ปลดระงับแล้ว');loadAdminUsers($('usr-q')?.value.trim())}catch(e){toast(e.message)}}
async function adminResetUserPassword(id){const pw=prompt('ตั้งรหัสผ่านใหม่ (อย่างน้อย 8 ตัว) ให้ผู้ใช้คนนี้:');if(!pw)return;try{await api('/admin/users/'+id+'/reset-password',{method:'POST',headers:adminHeaders(),body:JSON.stringify({password:pw})});toast('รีเซ็ตรหัสผ่านแล้ว')}catch(e){toast(e.message)}}
async function adminDeleteUser(id,username){if(!confirm('ลบบัญชี '+username+' ถาวร? คำสั่งซื้อและข้อมูลที่เชื่อมโยงทั้งหมดจะถูกลบไปด้วย'))return;try{await api('/admin/users/'+id,{method:'DELETE',headers:adminHeaders()});toast('ลบบัญชีแล้ว');loadAdminUsers($('usr-q')?.value.trim())}catch(e){toast(e.message)}}

// --- Xbox links admin view (read-only) ---
async function loadAdminXbox(q){try{const qs=new URLSearchParams(q?{q}:{});const d=await api('/admin/xbox-links?'+qs.toString(),{headers:adminHeaders()});$('admin-xbox').innerHTML=`<div class="card form-card"><div class="card-title"><b>Linked Xbox accounts</b><span>${d.links.length} รายการล่าสุด</span></div><input id="xl-q" placeholder="ค้นหา user / gamertag / IGN" oninput="xlSearchDebounced()"><div class="admin-list">${d.links.map(x=>`<div class="admin-line"><span><b>${esc(x.gamertag)}</b><small>IGN: ${esc(x.igName)} · บัญชีเว็บ: ${esc(x.username)} · เชื่อมเมื่อ ${esc(x.createdAt)}</small></span></div>`).join('')||'<div class="empty">ยังไม่มีบัญชีที่เชื่อม</div>'}</div></div>`}catch(e){toast(e.message)}}
let xlDebounceT;function xlSearchDebounced(){clearTimeout(xlDebounceT);xlDebounceT=setTimeout(()=>loadAdminXbox($('xl-q').value.trim()),350)}

// --- Admin 2FA (self-service, any role) ---
async function open2faModal(){try{const d=await api('/admin/me',{headers:adminHeaders()});if(d.admin.totpEnabled)render2faDisable();else render2faSetup();$('admin-2fa-modal').classList.add('show')}catch(e){toast(e.message)}}
function render2faDisable(){$('admin-2fa-body').innerHTML=`<p style="color:var(--muted);font-size:.82rem">บัญชีนี้เปิด 2FA อยู่ กรอกรหัส 6 หลักปัจจุบันเพื่อปิด 2FA</p><input id="2fa-disable-code" placeholder="123456" maxlength="6"><button class="btn danger full" onclick="disable2fa()" style="margin-top:8px">ปิด 2FA</button><div id="2fa-disable-msg" class="msg"></div>`}
async function disable2fa(){try{await api('/admin/2fa/disable',{method:'POST',headers:adminHeaders(),body:JSON.stringify({code:$('2fa-disable-code').value.trim()})});toast('ปิด 2FA แล้ว');$('admin-2fa-modal').classList.remove('show')}catch(e){$('2fa-disable-msg').textContent=e.message}}
async function render2faSetup(){try{const d=await api('/admin/2fa/setup',{method:'POST',headers:adminHeaders()});$('admin-2fa-body').innerHTML=`<p style="color:var(--muted);font-size:.82rem">สแกน QR นี้ด้วยแอป Google Authenticator / Authy หรือกรอกคีย์นี้เองก็ได้:</p><div class="totp-secret">${esc(d.secret)}</div><p style="color:var(--muted);font-size:.72rem">หรือเปิดลิงก์นี้ในแอป Authenticator: <a href="${esc(d.otpauthUrl)}" style="color:var(--cyan)">${esc(d.otpauthUrl)}</a></p><input id="2fa-confirm-code" placeholder="กรอกรหัส 6 หลักเพื่อยืนยัน" maxlength="6"><button class="btn primary full" onclick="confirm2faSetup('${d.setupToken}')" style="margin-top:8px">ยืนยันและเปิดใช้งาน</button><div id="2fa-setup-msg" class="msg"></div>`}catch(e){toast(e.message)}}
async function confirm2faSetup(setupToken){try{await api('/admin/2fa/confirm',{method:'POST',headers:adminHeaders(),body:JSON.stringify({setupToken,code:$('2fa-confirm-code').value.trim()})});toast('เปิดใช้งาน 2FA สำเร็จ');$('admin-2fa-modal').classList.remove('show')}catch(e){$('2fa-setup-msg').textContent=e.message}}

// --- Coupons ---
S.couponsLoaded=false;
async function loadAdminCoupons(){try{const d=await api('/admin/coupons',{headers:adminHeaders()});renderAdminCoupons(d.coupons)}catch(e){toast(e.message)}}
function renderAdminCoupons(list){const locked=S.admin.role==='moderator';$('admin-coupons').innerHTML=`<div class="card form-card"><div class="card-title"><b>Coupons</b><span>${list.length} โค้ด</span></div>${locked?'':`<div class="admin-editor-grid" style="grid-template-columns:repeat(2,1fr)"><input id="cp-code" placeholder="CODE เช่น SAVE20"><select id="cp-type"><option value="percent">เปอร์เซ็นต์ %</option><option value="fixed">ลดคงที่ (บาท)</option></select><input id="cp-value" type="number" step="0.01" placeholder="มูลค่า"><input id="cp-max" type="number" placeholder="จำนวนครั้งใช้ได้สูงสุด (เว้นว่าง=ไม่จำกัด)"><input id="cp-exp" type="date" placeholder="วันหมดอายุ"></div><button class="btn primary" onclick="adminCreateCoupon()">สร้างโค้ด</button><div id="cp-msg" class="msg"></div>`}<div class="admin-list">${list.map(c=>`<div class="admin-line"><span><b>${esc(c.code)}</b><small>${c.type==='percent'?c.value+'%':'฿'+c.value} · ใช้ไปแล้ว ${c.usedCount}${c.maxUses!=null?'/'+c.maxUses:''} · ${c.expiresAt?'หมดอายุ '+esc(c.expiresAt.slice(0,10)):'ไม่มีวันหมดอายุ'} · ${c.active?'เปิดใช้งาน':'ปิดใช้งาน'}</small></span>${locked?'':`<span style="display:flex;gap:6px"><button class="btn ghost small" onclick="adminToggleCoupon('${esc(c.code)}',${c.active?0:1})">${c.active?'ปิด':'เปิด'}</button><button class="btn danger small" onclick="adminDeleteCoupon('${esc(c.code)}')">ลบ</button></span>`}</div>`).join('')||'<div class="empty">ยังไม่มีโค้ดส่วนลด</div>'}</div></div>`}
async function adminCreateCoupon(){try{await api('/admin/coupons',{method:'POST',headers:adminHeaders(),body:JSON.stringify({code:$('cp-code').value.trim(),type:$('cp-type').value,value:$('cp-value').value,maxUses:$('cp-max').value,expiresAt:$('cp-exp').value})});toast('สร้างโค้ดแล้ว');loadAdminCoupons()}catch(e){$('cp-msg').textContent=e.message}}
async function adminToggleCoupon(code,active){try{await api('/admin/coupons/'+encodeURIComponent(code),{method:'PATCH',headers:adminHeaders(),body:JSON.stringify({active:!!active})});loadAdminCoupons()}catch(e){toast(e.message)}}
async function adminDeleteCoupon(code){if(!confirm('ลบโค้ด '+code+'?'))return;try{await api('/admin/coupons/'+encodeURIComponent(code),{method:'DELETE',headers:adminHeaders()});toast('ลบโค้ดแล้ว');loadAdminCoupons()}catch(e){toast(e.message)}}

// --- Sales dashboard ---
async function loadAdminSales(days){days=days||30;try{const d=await api('/admin/stats/sales?days='+days,{headers:adminHeaders()});renderAdminSales(d,days)}catch(e){toast(e.message)}}
function renderAdminSales(d,days){const max=Math.max(1,...d.series.map(x=>x.revenue||0));const bars=d.series.map(x=>`<div class="sales-bar" style="height:${Math.max(3,(x.revenue||0)/max*100)}%" title="${esc(x.day)}: ฿${Number(x.revenue||0).toFixed(2)}"><span>${x.day.slice(5)}</span></div>`).join('');$('admin-sales').innerHTML=`<div class="card form-card"><div class="card-title"><b>Sales</b><span><button class="btn ghost small" onclick="loadAdminSales(7)">7 วัน</button> <button class="btn ghost small" onclick="loadAdminSales(30)">30 วัน</button> <button class="btn ghost small" onclick="loadAdminSales(90)">90 วัน</button></span></div><div class="admin-stats"><div class="admin-stat card"><small>คำสั่งซื้อที่จ่ายแล้ว</small><b>${d.totalOrders}</b></div><div class="admin-stat card"><small>รายได้รวม (${days} วัน)</small><b>฿${d.totalRevenue.toFixed(2)}</b></div></div>${d.series.length?`<div class="sales-bars">${bars}</div>`:'<div class="empty">ยังไม่มียอดขายในช่วงนี้</div>'}</div>`}

init();initAdminSection();
